 rt.right=true;check(!menu.hold_selection_step(s,rt)&&menu.hold_selection_state().choice()->item==3,"preview selects owned Operator");check(menu.cues()==std::vector<unsigned>{menu_audio::Cursor},"one cursor sound");capture("hold_weapon_operator.bmp");menu.hold_selection_step(s,rt);check(menu.cues().empty(),"held direction has no sound repeat");
 check(menu.message(nullptr,WM_KEYDOWN,VK_RETURN,0)&&menu.message(nullptr,WM_KEYDOWN,VK_RETURN,1LL<<30),"Enter consumed without commit");check(menu.hold_visible()&&menu.cues().empty(),"Enter cannot prematurely confirm");
