 rt.right=false;open();rt.left=true;menu.hold_selection_step(s,rt);capture("hold_weapon_grenade.bmp");check(menu.hold_selection_state().choice()->item==52,"left wrap selects owned grenade");menu.cues();
 check(menu.message(nullptr,WM_KEYDOWN,VK_ESCAPE,0)&&!menu.hold_visible(),"Escape cancels");check(menu.cues()==std::vector<unsigned>{menu_audio::Cancel},"cancel sound");check(!menu.hold_selection_step(s,{}),"cancel release cannot submit");
 menu.hold_selection_step(s,lt);check(menu.hold_visible()&&menu.hold_selection_state().choices().empty(),"empty equipment shown");capture("hold_equipment_empty.bmp");check(!menu.hold_selection_step(s,{})&&!menu.hold_visible(),"empty release cannot submit");check(menu.cues()==std::vector<unsigned>{menu_audio::Cancel},"empty release has no confirm");
 rt.left=false;open();menu.cues();menu.message(nullptr,WM_KILLFOCUS,0,0);check(!menu.hold_visible()&&!menu.hold_selection_step(s,{}),"focus loss cancels release");
 open();auto dead=s;dead.eligible=false;check(!menu.hold_selection_step(dead,{})&&!menu.hold_visible(),"death cancels");menu.cues();
